import java.util.*;

class Main {
    static class DSU {
        int[] parent;
        DSU(int n) { parent = new int[n]; for (int i = 0; i < n; i++) parent[i] = i; }
        int find(int x) {
            while (parent[x] != x) x = parent[x];
            return x;
        }
        void union(int a, int b) {
            a = find(a); b = find(b);
            if (a != b) parent[b] = a;
        }
    }
    public static void main(String[] args) {
        DSU dsu = new DSU(5);
        dsu.union(0, 1);
        dsu.union(3, 4);
        System.out.println(dsu.find(1) == dsu.find(0));
    }
}

